# Let me try to generate from LCF notation without networkx

def generate_from_lcf(lcf_list, n):
    """Generate edges from LCF notation."""
    edges = set()
    for i in range(n):
        for offset in lcf_list:
            j = (i + offset) % n
            u, v = (i, j) if i < j else (j, i)
            edges.add((u, v))
    return sorted(edges)

