from collections import deque

def find_girth(edges, n):
    adj = {i:set() for i in range(n)}
    for u,v in edges:
        adj[u].add(v)
        adj[v].add(u)

    min_cycle = float('inf')
    for start in range(n):
        dist = [-1]*n
        parent = [-1]*n
        q = deque([start])
        dist[start] = 0
        while q:
            u = q.popleft()
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    q.append(v)
                elif v != parent[u] and dist[v] >= dist[u]:
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len < min_cycle:
                        min_cycle = cycle_len
        if min_cycle == 3:
            break
    return min_cycle if min_cycle != float('inf') else 0

def can_3color(edges, n):
    adj = {i:set() for i in range(n)}
    for u,v in edges:
        adj[u].add(v)
        adj[v].add(u)
    colors = [-1]*n

    # Order by degree for efficiency
    order = sorted(range(n), key=lambda x: len(adj[x]), reverse=True)

    def dfs(idx):
        if idx == n:
            return True
        v = order[idx]
        used = set()
        for u in adj[v]:
            if colors[u] != -1:
                used.add(colors[u])
        for c in range(3):
            if c not in used:
                colors[v] = c
                if dfs(idx+1):
                    return True
                colors[v] = -1
        return False
    return dfs(0), colors[:]

