# LCF notation: a sequence [a_0,...,a_{n-1}] defines a cubic graph:
# - The Hamiltonian cycle: (i, i+1 mod n) for all i
# - Chords: (i, i + a_i mod n) for all i

def generate_from_lcf(lcf_full, n):
    """Generate edges from full LCF sequence (length n)."""
    edges = set()
    for i in range(n):
        # Hamiltonian cycle edge
        j = (i + 1) % n
        u, v = (i, j) if i < j else (j, i)
        edges.add((u, v))

        # Chord edge
        j = (i + lcf_full[i]) % n
        u, v = (i, j) if i < j else (j, i)
        edges.add((u, v))
    return sorted(edges)

